+		if err := decoder.Decode(&record); err != nil {
+			return semanticRecord{}, err
+		}
+		if record.RecordType != "symbol" {
+			continue
+		}
+		if record.ID == idOrName || record.Name == idOrName || record.QualifiedName == idOrName {
