+func rankHistoryRecords(index historyIndex, kind, query string, limit int) []historyRecord {
+	if limit <= 0 {
+		return nil
+	}
+	allowed := historyInspectKinds(kind)
+	scored := make([]scoredHistoryRecord, 0, min(len(index.Records), limit))
+	seen := map[string]struct{}{}
